 cards:'m7 3 13 2-2 16-13-2z M4 6 2 18l3 1 M9 10l6 1 M9 14l4 1',
 pen:'m15 4 5 5 M4 16 16 4a3 3 0 0 1 4 4L8 20l-5 1z',
 calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2 M7 3v4 M17 3v4 M3 10h18 M7 14h2 M15 14h2 M7 17h2',
 chart:'M4 3v18h17 M8 16v-5 M13 16V7 M18 16V4',
 settings:'m9 3-1 3-3 1-2 3 2 2-1 3 3 3 3-1 2 2 3-1 1-3 3-1 1-3-2-2 1-3-3-3-3 1z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
 search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M15 15l6 6',
 flame:'M13 2c1 5-4 6-2 9 1 1 3 0 3-3 6 5 5 12-1 14-6 1-11-5-7-11 0 4 2 5 3 3-3-6 4-7 4-12z',
 bolt:'m13 2-9 12h7l-1 8 10-12h-7z',
 target:'M21 12a9 9 0 1 1-9-9 M17 12a5 5 0 1 1-5-5 M12 12l9-9 M17 3h4v4',
 clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',
 check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',plus:'M12 5v14 M5 12h14',
 chevron:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',
 star:'m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z',
 sprout:'M12 22V12 M12 15C3 16 2 10 3 6c7-1 10 2 9 9 M12 12c0-8 4-10 9-9 1 6-3 10-9 9',
 sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',
 people:'M10 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M17 10a3 3 0 1 0-3-3 M2 21v-3a5 5 0 0 1 10 0v3 M16 14a5 5 0 0 1 5 5v2',
 wave:'M7 13 4 8a2 2 0 0 1 3-2l4 6-4-8a2 2 0 0 1 3-1l4 8-2-7a2 2 0 0 1 3 0l3 9V9a2 2 0 0 1 4 0v6c0 8-10 10-14 4l-5-5a2 2 0 0 1 3-3z',
 home:'m2 11 10-8 10 8 M5 9v12h14V9 M9 21v-8h6v8',
 trophy:'M7 3h10v6a5 5 0 0 1-10 0z M7 5H3v3a4 4 0 0 0 5 4 M17 5h4v3a4 4 0 0 1-5 4 M12 14v6 M8 21h8',
 sound:'M3 9h4l5-4v14l-5-4H3z M16 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14',
 flip:'M4 7h13l-3-3 M20 17H7l3 3 M20 7v5 M4 17v-5',
